static void bgp_nht_ifp_table_handle(struct bgp *bgp,
				     struct bgp_nexthop_cache_head *table,
				     struct interface *ifp, bool up)
{
	struct bgp_nexthop_cache *bnc;

	if (ifp->ifindex == IFINDEX_INTERNAL) {
		zlog_warn("%s: The interface %s ignored", __func__, ifp->name);
		return;
	}

	frr_each (bgp_nexthop_cache, table, bnc) {
		if (!(**bnc->nexthop_num == 1** && bnc->nexthop &&   **<<<<<<<<<<<< For non v6_ll case, UP case would get skipped**
		      bnc->nexthop->ifindex == ifp->ifindex) &&
		    (bnc->ifindex_ipv6_ll != ifp->ifindex))
			continue;

		bnc->last_update = monotime(NULL);
		bnc->change_flags = 0;

		/*
		 * For interface based routes ( ala the v6 LL routes
		 * that this was written for ) the metric received
		 * for the connected route is 0 not 1.
		 */
		bnc->metric = 0;
		if (up) {
			struct nexthop *nh;

			/* Clear PEER_NOTIFIED so evaluate_paths() always
			 * re-notifies the FSM on an UP transition.
			 */
			UNSET_FLAG(bnc->flags, BGP_NEXTHOP_PEER_NOTIFIED);
			SET_FLAG(bnc->flags, BGP_NEXTHOP_VALID);
			SET_FLAG(bnc->change_flags, BGP_NEXTHOP_CHANGED);

			bnc_nexthop_free(bnc);
			nh = nexthop_new();
			nh->type = NEXTHOP_TYPE_IFINDEX;
			nh->ifindex = ifp->ifindex;
			nh->vrf_id = ifp->vrf->vrf_id;
			bnc->nexthop = nh;
			bnc->nexthop_num = 1;
		} else {
			UNSET_FLAG(bnc->flags, BGP_NEXTHOP_PEER_NOTIFIED);
			UNSET_FLAG(bnc->flags, BGP_NEXTHOP_VALID);
			SET_FLAG(bnc->change_flags, BGP_NEXTHOP_CHANGED);
			bnc_nexthop_free(bnc);
			bnc->nexthop = NULL;
			bnc->nexthop_num = 0;    <<<<<<<<<< **Down case: sets nexthop_num=0**
		}

		evaluate_paths(bnc);
	}
}
```

@Xichen96, We could face the same issue as seen for multi-asic platforms. If `rsyslog.service` starts before `docker.service`, docker0 interface won't exist. In this case, the forwarded logs are then silently dropped even though the iptables rule is correct.

See issue: https://github.com/sonic-net/sonic-buildimage/issues/27236. It was fixed via https://github.com/sonic-net/sonic-buildimage/pull/27548

I think we should add a similar fix.

